import type { ViewRegistry } from "./model.ts";

/** Path of the generated registry module, from the package root. */
export const GENERATED_PATH = "src/views/registry.generated.ts";

/** The generated TypeScript module holding the view registry, for apps that cannot read files. */
export function renderViewRegistryModule(registry: ViewRegistry): string {
  return [
    "// Generated by `pnpm --filter @xos/schemas generate:views` from packages/schemas/views.yaml.",
    "// Never edit by hand; on a merge conflict, take either side and rerun the generator.",
    'import type { ViewRegistry } from "./model.ts";',
    "",
    `export const VIEW_REGISTRY: ViewRegistry = ${JSON.stringify(registry, null, 2)};`,
    "",
  ].join("\n");
}
